//! The routines that jump.
//!
//! 2182 of them, and they are the ones no tree can hold. Every other table of
//! recovered routines is a tree of steps, because a branch encloses what it
//! governs; a jump does not. A `goto` out of one block and into another has no
//! shape to record, so the walk that reads the rest of the program refuses
//! these outright. What can still be said of them truthfully is said here.
//!
//! Almost all of them jump once, to one place. 1199 of the 2182 have a single jump
//! and 1470 have a single label. Another 606 jump more times than they have
//! labels, which means several jumps arriving at the same place.
//!
//! And that place is nearly always the cleanup. Of everything called from the
//! last label onward, **33 in a hundred are the run time's releases** — against
//! 11 in a hundred across these routines' bodies as a whole, so the rate
//! roughly trebles at the label. 957 of the 2182 call nothing but releases after
//! their last label. That is what the jumps are for: a routine that has
//! acquired several things and meets a reason to stop jumps forward to the one
//! place that lets them all go, rather than repeating the releases down every
//! path. It is the pattern `goto` survives in C for, and the decompiler has
//! recovered it rather than invented it.
//!
//! The order of [`Jumping::calls`] is the order the calls are **written**, not
//! the order they run. For every other table those are the same thing. Here
//! they are not, and that is the price of the shape: the set of calls is
//! reliable, the sequence is not.

// The addresses are written without separators so the port-mapping importer can
// match them against the recovered functions.
#![allow(clippy::unreadable_literal)]

/// One routine whose control flow does not nest.
#[derive(Debug, Clone, Copy)]
pub struct Jumping {
    /// Where it sits.
    pub routine: u32,
    /// What it calls, in the order the calls are written.
    ///
    /// Not the order they run: a jump can reach any label from anywhere, so
    /// only the set of calls is reliable here.
    pub calls: &'static [u32],
    /// What it calls from its last label onward.
    ///
    /// The place the jumps converge, which is nearly always the cleanup.
    pub tail: &'static [u32],
    /// How many places it jumps to.
    pub labels: u16,
    /// How many jumps it makes.
    pub jumps: u16,
    /// How many loops it has.
    pub loops: u16,
    /// Whether it also calls through a thunk the decompiler could not resolve.
    pub through_a_thunk: bool,
}

/// The run-time routines that let something go.
pub const RELEASES: [u32; 12] = [
    0x00414480, 0x00414560, 0x004144D0, 0x00414520, 0x0041B800, 0x00414590, 0x004145C0, 0x00417740,
    0x00419430, 0x00417840, 0x00460B80, 0x00410F20,
];

