/// How many there are.
pub const JUMPING_COUNT: usize = 2182;

/// Implements part of the jumping family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Jumping> {
    JUMPING
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &JUMPING[at])
}

/// Implements part of the jumping family.
///
/// Whether one call lets something go.
#[must_use]
pub fn is_a_release(call: u32) -> bool {
    RELEASES.contains(&call)
}

/// Implements part of the jumping family.
///
/// Whether several jumps arrive at the same place.
#[must_use]
pub const fn jumps_converge(held: &Jumping) -> bool {
    held.jumps > held.labels
}

/// Implements part of the jumping family.
///
/// Whether a routine's last label does nothing but let things go.
///
/// Then the jump is an early exit to shared cleanup and nothing else.
#[must_use]
pub fn tail_is_only_cleanup(held: &Jumping) -> bool {
    !held.tail.is_empty() && held.tail.iter().all(|call| is_a_release(*call))
}

/// Implements part of the jumping family.
///
/// Every routine whose jumps go to cleanup and nowhere else.
#[must_use]
pub fn jump_to_cleanup() -> Vec<&'static Jumping> {
    JUMPING
        .iter()
        .filter(|held| tail_is_only_cleanup(held))
        .collect()
}

/// Implements part of the jumping family.
///
/// What share of the calls made from the last label onward are releases.
///
/// Compare [`share_of_releases_in_bodies`]: the rate roughly trebles at the
/// label, which is what says the jumps are going to the cleanup.
#[must_use]
pub fn share_of_releases_after_the_label() -> f64 {
    let every: usize = JUMPING.iter().map(|held| held.tail.len()).sum();
    if every == 0 {
        return 0.0;
    }
    let releases = JUMPING
        .iter()
        .flat_map(|held| held.tail.iter())
        .filter(|call| is_a_release(**call))
        .count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        releases as f64 / every as f64
    }
}

/// Implements part of the jumping family.
///
/// What share of all the calls these routines make are releases.
#[must_use]
pub fn share_of_releases_in_bodies() -> f64 {
    let every: usize = JUMPING.iter().map(|held| held.calls.len()).sum();
    if every == 0 {
        return 0.0;
    }
    let releases = JUMPING
        .iter()
        .flat_map(|held| held.calls.iter())
        .filter(|call| is_a_release(**call))
        .count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few tens of thousands, well inside what a double holds exactly"
    )]
    {
        releases as f64 / every as f64
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(JUMPING.len(), JUMPING_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            JUMPING
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = JUMPING[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn every_one_of_them_jumps_at_least_once() {
        // Which is the whole of what puts them here rather than in a tree.
        for held in &JUMPING {
            assert!(held.jumps >= 1, "{:#010X}", held.routine);
            assert!(held.labels >= 1, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn none_of_them_could_be_read_as_a_tree() {
        for held in JUMPING.iter().take(400) {
            assert!(crate::nested_routines::routine_at(held.routine).is_none());
            assert!(crate::deeper_routines::routine_at(held.routine).is_none());
            assert!(crate::looping_routines::routine_at(held.routine).is_none());
            assert!(crate::substantial_routines::routine_at(held.routine).is_none());
            assert!(crate::remaining_routines::routine_at(held.routine).is_none());
        }
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        for held in &JUMPING {
            for call in held.calls.iter().chain(held.tail.iter()) {
                assert!(
                    (0x0040_6DE0..=0x01D8_7790).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn most_of_them_jump_once_to_one_place() {
        let simple = JUMPING
            .iter()
            .filter(|held| held.jumps == 1 && held.labels == 1)
            .count();

        assert!(simple * 2 > JUMPING.len(), "{simple} of {}", JUMPING.len());
    }

    #[test]
    fn some_of_them_have_several_jumps_arriving_at_one_place() {
        let converging = JUMPING.iter().filter(|held| jumps_converge(held)).count();

        assert!(converging > 0);
        for held in JUMPING.iter().filter(|held| jumps_converge(held)).take(50) {
            assert!(held.jumps > held.labels, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn the_place_they_jump_to_is_nearly_always_the_cleanup() {
        // The rate of releases roughly trebles at the label. That is what says
        // the jumps are early exits to one place that lets everything go.
        let after = share_of_releases_after_the_label();
        let across = share_of_releases_in_bodies();

        assert!(after > across * 2.0, "{after} against {across}");
    }

    #[test]
    fn and_many_of_them_do_nothing_else_after_it() {
        let cleanup = jump_to_cleanup().len();

        assert!(
            cleanup * 4 > JUMPING.len(),
            "{cleanup} of {}",
            JUMPING.len()
        );
        for held in jump_to_cleanup().iter().take(100) {
            assert!(held.tail.iter().all(|call| is_a_release(*call)));
        }
    }

    #[test]
    fn a_routine_with_nothing_after_its_label_is_not_counted_as_cleanup() {
        let empty = Jumping {
            routine: 0x0040_7000,
            calls: &[],
            tail: &[],
            labels: 1,
            jumps: 1,
            loops: 0,
            through_a_thunk: false,
        };

        assert!(!tail_is_only_cleanup(&empty));
    }

    #[test]
    fn the_releases_are_the_ones_recovered_earlier() {
        for call in RELEASES {
            assert!(is_a_release(call), "{call:#010X}");
        }
        assert!(!is_a_release(0));
    }

    #[test]
    fn every_routine_calls_something() {
        for held in &JUMPING {
            assert!(!held.calls.is_empty(), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn what_a_routine_calls_after_its_label_it_also_calls_somewhere() {
        for held in JUMPING.iter().take(300) {
            for call in held.tail {
                assert!(held.calls.contains(call), "{call:#010X}");
            }
        }
    }

    #[test]
    fn many_of_them_have_a_loop_as_well() {
        let looping = JUMPING.iter().filter(|held| held.loops > 0).count();

        assert!(looping > JUMPING.len() / 4, "{looping}");
    }

    #[test]
    fn some_of_them_call_through_a_thunk() {
        let thunked = JUMPING.iter().filter(|held| held.through_a_thunk).count();

        assert!(thunked > 0);
        assert!(thunked < JUMPING.len() / 2);
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = JUMPING.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
